import json
from pathlib import Path
root=Path(__file__).resolve().parents[1]
read=lambda n:json.loads((root/n).read_text())
write=lambda n,v:(root/n).write_text(json.dumps(v,ensure_ascii=False,separators=(',',':')))
words=read('data.json');expressions=read('expressions.json');refs=read('reference.json');units=read('curriculum.json');domains=read('domains.json')
