for e in expressions:meta['e'+e['id']]={'categories':[],'expressionType':'unreviewed','register':'unreviewed','topics':[],'origin':{'language':'unreviewed'},'review':'pending','sourceMetadata':{'type':e['type'],'register':e.get('register'),'topic':e.get('category')},'contexts':[]}
everyday=set('hello name please thank help need friend family neighbour teacher student guest ask answer bring leave wait share early late usually often before after near between opposite entrance corner direction meal fresh hungry thirsty order prefer price change receipt afford discount return journey destination departure delay reserve route calm worried proud disappointed encourage patient notice repair replace solution careful urgent goal prepare schedule priority organise complete explain describe agree suggest clarify respond focus review practice progress feedback strategy task responsibility contribute cooperate deadline reliable context detail purpose opinion evidence infer similar contrast benefit limitation significant alternative introduce develop support however therefore conclude accurate precise consistent approximate tentative plausible impact consequence factor adapt sustain policy access accountability coherent subtle'.split())
academic=set('context evidence infer contrast limitation significant introduce develop support however therefore conclude investigate method sample observe analyse interpret claim assumption justify valid bias evaluate accurate precise consistent approximate tentative plausible factor corroborate empirical synthesise discrepancy inherent nuance'.split())
formal=set('mitigate corroborate empirical synthesise scrutinise inherent discrepancy accountability'.split())
business=set('task responsibility contribute cooperate deadline reliable schedule priority organise complete'.split())
core_topics={'First conversations':'Communication','People around you':'Relationships','Everyday actions':'Daily life','Time and routine':'Daily life','Places and directions':'Travel','Food and daily needs':'Food','Buying and paying':'Shopping','Travel plans':'Travel','Feelings and support':'Relationships','Solving small problems':'Daily life','Making plans':'Daily life','Clear conversations':'Communication','Learning effectively':'Education','Working together':'Workplace','Reading for meaning':'Reading and writing','Comparing ideas':'Reading and writing','Writing with a clear structure':'Reading and writing','Questions and research':'Research','Evaluating an argument':'Research','Precision and uncertainty':'Research','Change and consequences':'Society','Society and public decisions':'Politics','Nuance in demanding texts':'Reading and writing','From evidence to insight':'Research'}
def assign(key,categories,topic,register,context,expression_type='word'):
 m=meta[key];m['review']='editorial';m['categories']=sorted(set(m['categories']+categories));m['topics']=sorted(set(m['topics']+[topic]));m['expressionType']=expression_type
 if m['register']=='unreviewed':m['register']=register
 elif m['register']!=register:m['register']='sense-dependent'
 context.update(categories=categories,topic=topic,register=register);m['contexts'].append(context)
for u in units:
 for e in u['lessons']:
  cs=[]
  if e['word'] in everyday:cs.append('everyday')
  if e['word'] in academic:cs.append('academic')
  if e['word'] in formal:cs.append('formal')
  if e['word'] in business:cs.append('business')
  if e['word'] in {'however','therefore','before','after'}:cs.append('linker')
  reg='formal' if e['word'] in formal else 'neutral'
  assign('w'+str(e['wordId']),cs,core_topics[u['title']],reg,{'meaning':e['meaning'],'pos':e['pos'],'example':e['example'],'urdu':e['urdu'],'contextId':u['id'],'rationale':'Classification describes this original teaching sense; not every sense of the headword.'})
technical=set('warranty installment subscription itinerary layover boarding baggage fare gratuity allergen dietary onboarding appraisal probation reimbursement revenue overhead inventory procurement stakeholder outsourcing franchise turnover deposit withdrawal collateral liquidity premium deductible symptom prescription dosage referral outpatient triage contraindication authentication phishing malware encryption bandwidth interface algorithm database debug variable deployment repository schema latency curriculum rubric scaffolding formative summative literacy prerequisite methodology corpus triangulation paraphrase citation plagiarism replication confounder jurisdiction affidavit litigation statute liability appeal defendant plaintiff constituency ballot ordinance municipal petition bureaucracy biodiversity ecosystem emissions renewable landfill compost conservation specimen calibration reagent solvent control hypothesis precision accuracy denominator numerator ratio proportion median outlier premise inference blueprint load tolerance maintenance insulation ventilation scaffold corrosion irrigation seedling fertilizer livestock arable yield pesticide attribution misinformation disinformation metaphor imagery protagonist motif satire allusion curator doctrine scripture interfaith secular estuary archipelago plateau urbanization diplomacy demography sovereignty'.split())
academic2=set('methodology corpus triangulation paraphrase citation plagiarism replication confounder hypothesis precision accuracy premise inference attribution corroborate nuance metaphor imagery motif allusion'.split())
literary=set('metaphor imagery protagonist motif satire allusion'.split())
business2=set('onboarding deadline delegate appraisal resignation vacancy probation reimbursement revenue overhead inventory procurement stakeholder outsourcing franchise turnover budget deposit withdrawal interest collateral liquidity premium deductible retailer stock'.split())
simple2=set('errand chore laundry utensil pantry clutter commute leak receipt refund checkout ingredient portion utensils simmer buffet deadline vacancy budget symptom consent backup permission feedback literacy ballot petition transparency drought harvest headline overwhelmed reassurance resentment empathy boundary compromise reconcile gratitude rehearsal heritage custom migration although unless whereas despite within across whether otherwise'.split())
topic_names=['Daily life','Shopping','Travel','Food','Workplace','Business','Finance','Health','Technology','Programming','Education','Research','Law','Politics','Environment','Science','Mathematics','Engineering','Agriculture','Media','Relationships','Literature','Culture and religion','Geography','Grammar']
for d,topic in zip(domains,topic_names):
 for e in d['lessons']:
  cs=[]
  if e['word'] in technical:cs.append('technical')
  if e['word'] in academic2:cs.append('academic')
  if e['word'] in literary:cs.append('literary')
  if e['word'] in business2:cs.append('business')
  if e['word'] in simple2:cs.append('everyday')
  if e['word'] in {'although','unless','whereas','despite','whether','otherwise'}:cs.append('linker')
  assign('w'+str(e['wordId']),cs,topic,'neutral',{'meaning':e['meaning'],'pos':e['pos'],'example':e['example'],'urdu':e['urdu'],'contextId':d['id'],'rationale':'Explicitly reviewed in the supplied practical-topic teaching sense.'})
