for phrase,(cat,register,topic,meaning,example,translation,tip,grammar) in reviewed.items():
 e=next(x for x in expressions if x['phrase']==phrase);e.update(register=register,meaning=meaning,example=example,exampleUrdu=translation,usageTip=tip,explanation=meaning+' '+tip)
 cats=[] if phrase=='look after' else [cat]
 if register=='informal':cats.append('informal')
 if cat=='phrasal' and phrase=='carry out':cats+=['academic','business']
 if phrase in {'put off','turn down','bring up','come up with'}:cats.append('business')
 if phrase in {'by and large','in a nutshell','at the end of the day'}:cats.append('linker')
 assign('e'+e['id'],cats,topic,register,{'meaning':meaning,'pos':('verb' if 'verb' in grammar.lower() or cat=='collocation' else 'adjective' if phrase=='under the weather' else 'adverb' if cat in {'fixed','idiom'} else 'sentence'),'structure':grammar,'example':example,'rationale':'Individually revised expression sense, grammar and register.'},grammar)
 if 'verb' in grammar.lower():e['verbType']=grammar;e['separability']='inseparable' if 'inseparable' in grammar else 'intransitive' if 'intransitive' in grammar else 'separable'
# Only documented borrowing origins; no blanket inference from Latin-looking spelling.
for term,url in [('genre','https://www.oxfordlearnersdictionaries.com/us/definition/english/genre'),('cafe','https://www.oxfordlearnersdictionaries.com/definition/english/cafe')]:
 w=next((w for w in refs if w['word']==term),None)
 if w:meta['r'+w['id']]={'categories':['borrowed']+(['literary'] if term=='genre' else []),'expressionType':'word','register':'neutral','topics':['Literature' if term=='genre' else 'Food'],'origin':{'language':'French','source':url},'review':'editorial','contexts':[{'meaning':w['senses'][0]['meaning'],'pos':w['senses'][0]['pos'],'categories':['borrowed']+(['literary'] if term=='genre' else []),'register':'neutral','topic':'Literature' if term=='genre' else 'Food','rationale':'Documented French borrowing; reference-only entry.'}]}
counts={id:sum(id in m['categories'] for m in meta.values()) for id,_,_,_ in catalog}
write('taxonomy.json',{'schemaVersion':1,'categories':[{'id':id,'name':name,'group':group,'icon':icon,'count':counts[id]} for id,name,group,icon in catalog],'entries':{key:m for key,m in meta.items() if m['review']=='editorial'},'notes':'Categories are sense-specific editorial assignments. Inherited labels are retained as sourceMetadata, not treated as verified classification. Category totals overlap. Empty categories are not populated with invented material.'})
write('classification-review.json',[{'key':key,'reason':'No new sense-by-sense classification review completed','sourceMetadata':m.get('sourceMetadata',{})} for key,m in meta.items() if m['review']=='pending'])
write('expressions.json',expressions)
audit=read('quality-audit.json');audit.update(classifiedEntries=sum(m['review']=='editorial' for m in meta.values()),classificationPending=sum(m['review']=='pending' for m in meta.values()),reviewedExpressions=len(reviewed),emptyCategories=[name for id,name,_,_ in catalog if not counts[id]],categoryCounts=counts);audit['dictionaryClassificationPending']=len(refs)-2
write('quality-audit.json',audit)
print({'classified':audit['classifiedEntries'],'pending':audit['classificationPending'],'reviewedExpressions':len(reviewed),'categoryCounts':counts})
